INSERT INTO _fleet_sync_epoch_history(database,epoch,holder,granted_at,ended_epoch,ended_sequence,created_at,updated_at) VALUES(?1,?2,json_extract(?3,'$.holder'),json_extract(?3,'$.granted_at'),NULLIF(?3 -> '$.ended_at.epoch','null'),NULLIF(?3 -> '$.ended_at.sequence','null'),CAST(?4 AS INTEGER),CAST(?5 AS INTEGER)) ON CONFLICT(database,epoch) DO UPDATE SET holder=excluded.holder,granted_at=excluded.granted_at,ended_epoch=excluded.ended_epoch,ended_sequence=excluded.ended_sequence,updated_at=excluded.updated_at
